findings.suggestion:
if (threads.length > 0) {
  // The poster files its review on whatever the head is when it posts, but
  // pins its status to the sha it reviewed: no status here means the threads
  // may be an earlier head's review.
  if (review.headStatus === undefined || review.headStatus.state === 'PENDING') {
    return {
      refusal:
        `The review bot's threads on ${prUrl} sit on ${head}, but it set no verdict ` +
        'status on that head, so the run that wrote them may have reviewed an earlier one; ' +
        'wait for the review of the head, then re-run.',
    };
  }
  return { head, threads };
}
